		operations.templates?.listAll,
		"templates.listAll",
		execution,
	);
	const pageSize = 100;
	const pages_scanned =
		templates.pageCount ?? Math.ceil(templates.length / pageSize);
	const matches = templates.slice(0, maxPages * pageSize).filter((template) =>
		text(template.title as ApiValue)
			.toLocaleLowerCase()
			.includes(query),
	);
	return {
		query,
		matches,
		pages_scanned,
		complete: pages_scanned <= maxPages,
	};
