import { Effect } from "effect";
import { createHevyClient, type HevyClient } from "@hevy-mcp/hevy-client";

type RequestConfig = {
	readonly url?: string;
	readonly method?: string;
	readonly path?: RequestPath;
	readonly query?: RequestQuery;
	readonly body?: unknown;
	readonly signal?: AbortSignal;
	readonly hevyDeadline?: number;
	readonly hevyTimeoutMs?: number;
};

type RequestPath = {
	readonly workoutId?: string;
	readonly routineId?: string;
	readonly exerciseTemplateId?: string;
	readonly folderId?: string;
	readonly date?: string;
};

type RequestQuery = {
	readonly page?: number;
	readonly pageSize?: number;
	readonly since?: string;
	readonly start_date?: string;
	readonly end_date?: string;
};

type RequestOptions = {
	readonly signal?: AbortSignal;
	readonly deadline?: number;
	readonly timeoutMs?: number;
};

type RequestEffectResponse = {
	readonly data: unknown;
	readonly status: number;
	readonly statusText: string;
	readonly headers: Headers;
};

type RequestEffect = (
	config: RequestConfig,
) => Effect.Effect<RequestEffectResponse, unknown>;

/**
 * Keep CLI test doubles compatible with the operations package's private
 * request-Effect seam while retaining Promise-shaped method spies for the
 * command assertions.
 */
export function createEffectClient(methods: Partial<HevyClient>): HevyClient {
	const native = createHevyClient({
		apiKey: "test-key",
		maxGetRetries: 0,
	});
	const seam = Object.getOwnPropertySymbols(native).find((symbol) =>
		symbol.description?.includes("native-request-effect"),
	);
	if (seam === undefined) {
		throw new Error("Missing native request Effect seam in test client");
	}
	const client = Object.assign(
		Object.create(Object.getPrototypeOf(native)),
		native,
		methods,
	) as HevyClient;
	Object.defineProperty(client, seam, {
		configurable: false,
		enumerable: false,
		value: ((config: RequestConfig) =>
			Effect.tryPromise({
				try: async () => ({
					data: await dispatch(methods, config),
					status: 200,
					statusText: "OK",
					headers: new Headers(),
				}),
				catch: (error) => error,
			})) satisfies RequestEffect,
		writable: false,
	});
	return client;
}

async function dispatch(
	methods: Partial<HevyClient>,
	config: RequestConfig,
): Promise<unknown> {
	const options = requestOptions(config);
	switch (config.url) {
		case "/v1/workouts": {
			if (config.method === "POST") {
				const method = methods.createWorkout;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getWorkouts;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/routines": {
			if (config.method === "POST") {
				const method = methods.createRoutine;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getRoutines;
			if (method === undefined) return {};
			return config.query === undefined
				? options === undefined
					? method()
					: method(undefined, options)
				: options === undefined
					? method(config.query)
					: method(config.query, options);
		}
		case "/v1/workouts/{workoutId}": {
			const workoutId = config.path?.workoutId;
			if (workoutId === undefined) return {};
			if (config.method === "PUT") {
				const method = methods.updateWorkout;
				if (method === undefined) return {};
				return options === undefined
					? method(workoutId, config.body as never)
					: method(workoutId, config.body as never, options);
			}
			const method = methods.getWorkout;
			if (method === undefined) return {};
			return options === undefined
				? method(workoutId)
				: method(workoutId, options);
		}
		case "/v1/routines/{routineId}": {
			const routineId = config.path?.routineId;
			if (routineId === undefined) return {};
			if (config.method === "PUT") {
				const method = methods.updateRoutine;
				if (method === undefined) return {};
				return options === undefined
					? method(routineId, config.body as never)
					: method(routineId, config.body as never, options);
			}
			const method = methods.getRoutineById;
			if (method === undefined) return {};
			return options === undefined
				? method(routineId)
				: method(routineId, options);
		}
		case "/v1/workouts/events": {
			const method = methods.getWorkoutEvents;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/workouts/count": {
			const method = methods.getWorkoutCount;
			if (method === undefined) return {};
			return options === undefined ? method() : method(options);
		}
		case "/v1/exercise_templates": {
			if (config.method === "POST") {
				const method = methods.createExerciseTemplate;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getExerciseTemplates;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/exercise_templates/{exerciseTemplateId}": {
			const method = methods.getExerciseTemplate;
			const exerciseTemplateId = config.path?.exerciseTemplateId;
			if (method === undefined || exerciseTemplateId === undefined) return {};
			return options === undefined
				? method(exerciseTemplateId)
				: method(exerciseTemplateId, options);
		}
		case "/v1/exercise_history/{exerciseTemplateId}": {
			const method = methods.getExerciseHistory;
			const exerciseTemplateId = config.path?.exerciseTemplateId;
			if (method === undefined || exerciseTemplateId === undefined) return {};
			return options === undefined
				? method(exerciseTemplateId, config.query)
				: method(exerciseTemplateId, config.query, options);
		}
		case "/v1/routine_folders": {
			if (config.method === "POST") {
				const method = methods.createRoutineFolder;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getRoutineFolders;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/routine_folders/{folderId}": {
			const method = methods.getRoutineFolder;
			const folderId = config.path?.folderId;
			if (method === undefined || folderId === undefined) return {};
			return options === undefined
				? method(folderId)
				: method(folderId, options);
		}
		case "/v1/body_measurements": {
			if (config.method === "POST") {
				const method = methods.createBodyMeasurement;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getBodyMeasurements;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/body_measurements/{date}": {
			const date = config.path?.date;
			if (date === undefined) return {};
			if (config.method === "PUT") {
				const method = methods.updateBodyMeasurement;
				if (method === undefined) return {};
				return options === undefined
					? method(date, config.body as never)
					: method(date, config.body as never, options);
			}
			const method = methods.getBodyMeasurement;
			if (method === undefined) return {};
			return options === undefined ? method(date) : method(date, options);
		}
		case "/v1/user/info": {
			const method = methods.getUserInfo;
			if (method === undefined) return {};
			const data =
				options === undefined ? await method() : await method(options);
			return { data };
		}
		default:
			return {};
	}
}

function requestOptions(config: RequestConfig): RequestOptions | undefined {
	if (
		config.signal === undefined &&
		config.hevyDeadline === undefined &&
		config.hevyTimeoutMs === undefined
	) {
		return undefined;
	}
	return {
		signal: config.signal,
		deadline: config.hevyDeadline,
		timeoutMs: config.hevyTimeoutMs,
	};
}

import {
	getV1BodyMeasurementsDatePathParamsSchema,
	getV1BodyMeasurementsQueryParamsSchema,
	getV1ExerciseHistoryExercisetemplateidPathParamsSchema,
	getV1ExerciseTemplatesExercisetemplateidPathParamsSchema,
	getV1WorkoutsEventsQueryParamsSchema,
	getV1RoutinesQueryParamsSchema,
	getV1RoutinesRoutineidPathParamsSchema,
	getV1WorkoutsQueryParamsSchema,
	getV1WorkoutsWorkoutidPathParamsSchema,
} from "@hevy-mcp/hevy-client/schemas";
import { z } from "zod";

const stringSchema = z.string();

function isString<T>(value: T): value is T & string {
	return stringSchema.safeParse(value).success;
}

interface UsageInput {
	[key: string]: string | undefined;
}

export interface CliArgs {
	command?: string;
	subcommand?: string;
	positionals: string[];
	options: Partial<Record<string, string | boolean>>;
}

export class UsageError extends Error {}

export class ConfigurationError extends Error {}

function stringOption(value: string | boolean | undefined): string | undefined {
	return isString(value) ? value : undefined;
}

function parseForUsage<T>(
	schema: z.ZodType<T>,
	value: string | undefined | UsageInput,
	labels: string | Record<string, string>,
	messages: Record<string, string> = {},
): T {
	try {
		return schema.parse(value);
	} catch (error) {
		if (!(error instanceof z.ZodError)) throw error;
		const issue = error.issues[0];
		const key = isString(issue?.path[0]) ? issue.path[0] : undefined;
		const label = isString(labels) ? labels : (key && labels[key]) || "Value";
		throw new UsageError(
			`${label} ${messages[key ?? "_"] ?? issue?.message ?? "is invalid"}`,
		);
	}
}

const safePositiveInteger = (message: string) =>
	z.number().int().refine(Number.isSafeInteger, message).min(1, message);

const paginationSchema = (
	source:
		| typeof getV1WorkoutsQueryParamsSchema
		| typeof getV1RoutinesQueryParamsSchema
		| typeof getV1BodyMeasurementsQueryParamsSchema,
) =>
	z.object({
		page: source.shape.page
			.pipe(safePositiveInteger("must be a positive integer"))
			.default(1),
		pageSize: source.shape.pageSize
			.pipe(
				z
					.number()
					.int()
					.refine(
						Number.isSafeInteger,
						"must be a positive integer no greater than 10",
					)
					.min(1, "must be a positive integer no greater than 10")
					.max(10, "must be a positive integer no greater than 10"),
			)
			.default(5),
	});

const eventOptionsSchema = z.object({
	page: getV1WorkoutsEventsQueryParamsSchema.shape.page
		.pipe(safePositiveInteger("must be a positive integer"))
		.default(1),
	pageSize: getV1WorkoutsEventsQueryParamsSchema.shape.pageSize
		.pipe(
			z
				.number()
				.int()
				.refine(
					Number.isSafeInteger,
					"must be a positive integer no greater than 10",
				)
				.min(1, "must be a positive integer no greater than 10")
				.max(10, "must be a positive integer no greater than 10"),
		)
		.default(5),
	since: getV1WorkoutsEventsQueryParamsSchema.shape.since.pipe(
		z.iso.datetime({
			offset: true,
			message: "must be an ISO timestamp",
		}),
	),
});

const historyDateSchema = z.iso.datetime({
	offset: true,
	message: "must be an ISO timestamp",
});
const exerciseHistoryOptionsSchema = z.object({
	start_date: z.string().pipe(historyDateSchema).optional(),
	end_date: z.string().pipe(historyDateSchema).optional(),
});

const safePathSegment = (message: string) =>
	z
		.string()
		.trim()
		.refine((value) => value.length > 0 && !/[/?#]/.test(value), message);
const workoutIdSchema =
	getV1WorkoutsWorkoutidPathParamsSchema.shape.workoutId.pipe(
		safePathSegment("is required and must be a safe path segment"),
	);
const routineIdSchema =
	getV1RoutinesRoutineidPathParamsSchema.shape.routineId.pipe(
		safePathSegment("is required and must be a safe path segment"),
	);
const exerciseIdSchema =
	getV1ExerciseTemplatesExercisetemplateidPathParamsSchema.shape.exerciseTemplateId.pipe(
		safePathSegment("is required and must be a safe path segment"),
	);
const exerciseHistoryIdSchema =
	getV1ExerciseHistoryExercisetemplateidPathParamsSchema.shape.exerciseTemplateId.pipe(
		safePathSegment("is required and must be a safe path segment"),
	);
const searchQuerySchema = safePathSegment(
	"is required and must be a safe search term",
);
const measurementDateSchema =
	getV1BodyMeasurementsDatePathParamsSchema.shape.date;
const weeksSchema = z.coerce
	.number()
	.max(520, "must be a positive integer no greater than 520")
	.pipe(safePositiveInteger("must be a positive integer no greater than 520"))
	.default(1);
const searchOptionsSchema = z.object({
	maxPages: z.coerce
		.number()
		.max(100, "must be a positive integer no greater than 100")
		.pipe(safePositiveInteger("must be a positive integer"))
		.default(10),
});

export function parsePagination(
	args: CliArgs,
	source:
		| typeof getV1WorkoutsQueryParamsSchema
		| typeof getV1RoutinesQueryParamsSchema
		| typeof getV1BodyMeasurementsQueryParamsSchema = getV1WorkoutsQueryParamsSchema,
